    private void jButton6ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton6ActionPerformed
        int fila = jTable1.getSelectedRow();
        if (fila > -1) {
            String idcur = jTable1.getValueAt(fila, 0).toString();
            String iddia = jTable1.getValueAt(fila, 1).toString();
            String horainicio = jTable1.getValueAt(fila, 2).toString();
            String horafin = jTable1.getValueAt(fila, 3).toString();

            txtHoraInicioCurDia.setText(horainicio);
            txtHoraFinCurDia.setText(horafin);
            txtIDCurso.setText(idcur);
            txtIDDia.setText(iddia);
        }
    }//GEN-LAST:event_jButton6ActionPerformed

